#!/usr/bin/env python3
# Generated by Claude Fable 5.1 (Anthropic), 2026-10-19
"""Report of rclcpp's IntraProcessManager registrations and matching (fishwait25 events, init-time only):
  python3 ipm_report.py <session_id> [--topic GLOB] [--json out.json]
Per process and per (process, topic): the intra-process publishers, the subscriptions with their buffer kind
(shared = callback takes shared_ptr<const Msg>, zero-copy delivery; ownership = the IPM copies for all but the last
ownership subscriber), the ring buffer depth, the matches the IPM made, the copy class of every publish, and the
subscriptions registered in the IPM whose take hook never fired (binary not compiled against the overlay headers).
Copy count per publish (IntraProcessManager::do_intra_process_publish, Humble): n_own = 0 -> 0; n_own > 0 and
n_shared <= 1 -> n_shared + n_own - 1; n_own > 0 and n_shared > 1 -> n_own (1 shared copy + n_own - 1)."""
import argparse, collections, fnmatch, json, sys
import psycopg2
DSN = 'host=localhost port=5432 dbname=fish user=fish password=fish'
ap = argparse.ArgumentParser(); ap.add_argument('session'); ap.add_argument('--topic', default=None); ap.add_argument('--json', default=None)
a = ap.parse_args()
con = psycopg2.connect(DSN); cur = con.cursor()
def ev(name):
    cur.execute("SELECT vpid, vtid, ts_ns, procname, payload FROM ros2_trace WHERE session_id=%s AND event=%s ORDER BY ts_ns", (a.session, name))
    return cur.fetchall()
nodes = {}
for vpid, _, _, _, p in ev('ros2:rcl_node_init'):
    ns = p.get('namespace') or '/'; nodes[(vpid, p['node_handle'])] = (ns.rstrip('/') + '/' + p['node_name']).replace('//', '/')
sub_rcl = {(vpid, p['subscription_handle']): (p['node_handle'], p['topic_name']) for vpid, _, _, _, p in ev('ros2:rcl_subscription_init')}
wait2rcl = {}                               # (vpid, waitable ptr) -> rcl subscription handle (Humble's second rclcpp_subscription_init)
for vpid, _, _, _, p in ev('ros2:rclcpp_subscription_init'):
    wait2rcl.setdefault((vpid, p['subscription']), p['subscription_handle'])
pub_rcl = {(vpid, p['publisher_handle']): (p['node_handle'], p['topic_name']) for vpid, _, _, _, p in ev('ros2:rcl_publisher_init')}
procname = {}
takes = collections.Counter(); ipubs = collections.Counter(); ipubs_addr = collections.Counter()
for vpid, _, _, pn, p in ev('ros2:fish_rclcpp_intra_take'):
    takes[(vpid, p['waitable'])] += 1
for vpid, _, _, pn, p in ev('ros2:fish_rclcpp_intra_publish'):
    ipubs[(vpid, p['publisher_handle'])] += 1
    if p.get('message') not in (None, '0x0', '0'): ipubs_addr[(vpid, p['publisher_handle'])] += 1
P = {}; S = {}; M = []
for vpid, _, ts, pn, p in ev('ros2:fish_rclcpp_ipm_add_publisher'):
    procname[vpid] = pn; nh, _ = pub_rcl.get((vpid, p['publisher_handle']), (None, None))
    P[(vpid, int(p['pub_id']))] = dict(vpid=vpid, pub_id=int(p['pub_id']), handle=p['publisher_handle'], topic=p['topic_name'],
                                       node=nodes.get((vpid, nh), '?'), ts=ts, n_ipub=ipubs[(vpid, p['publisher_handle'])],
                                       n_ipub_addr=ipubs_addr[(vpid, p['publisher_handle'])])
for vpid, _, ts, pn, p in ev('ros2:fish_rclcpp_ipm_add_subscription'):
    procname[vpid] = pn; rcl = wait2rcl.get((vpid, p['waitable'])); nh = sub_rcl.get((vpid, rcl), (None, None))[0] if rcl else None
    S[(vpid, int(p['sub_id']))] = dict(vpid=vpid, sub_id=int(p['sub_id']), waitable=p['waitable'], topic=p['topic_name'],
                                       take_shared=int(p['take_shared']), depth=int(p['depth']), node=nodes.get((vpid, nh), '?'),
                                       ts=ts, n_take=takes[(vpid, p['waitable'])])
for vpid, _, ts, pn, p in ev('ros2:fish_rclcpp_ipm_match'):
    M.append(dict(vpid=vpid, pub_id=int(p['pub_id']), sub_id=int(p['sub_id']), take_shared=int(p['take_shared']), ts=ts))
if not P and not S:
    print(f'{a.session}: no IPM events (image older than fishwait25 or whitelist without fish_rclcpp_ipm_*)'); sys.exit(1)
sel = lambda t: a.topic is None or fnmatch.fnmatch(t, a.topic)
print(f'session {a.session}: IPM in {len(set(list(procname)))} processes; {len(P)} intra-process publishers, {len(S)} intra-process '
      f'subscriptions ({sum(s["take_shared"] for s in S.values())} shared, {sum(1 - s["take_shared"] for s in S.values())} ownership), '
      f'{len(M)} matches')
by_pub = collections.defaultdict(list)
for m in M: by_pub[(m['vpid'], m['pub_id'])].append(m)
def copies(n_shared, n_own):
    return 0 if n_own == 0 else (n_shared + n_own - 1 if n_shared <= 1 else n_own)
rows = []
for key, pub in sorted(P.items(), key=lambda kv: (kv[1]['vpid'], kv[1]['topic'])):
    if not sel(pub['topic']): continue
    ms = by_pub.get(key, []); n_sh = sum(m['take_shared'] for m in ms); n_own = len(ms) - n_sh
    rows.append(dict(pub=pub, n_shared=n_sh, n_own=n_own, copies=copies(n_sh, n_own),
                     subs=[S.get((pub['vpid'], m['sub_id'])) for m in ms]))
print('\nper intra-process publisher (process, topic): matched subscriptions, buffer kinds, copies per publish')
cur_v = None
for r in rows:
    p = r['pub']
    if p['vpid'] != cur_v:
        cur_v = p['vpid']; print(f'\n== vpid {cur_v} {procname.get(cur_v, "")}')
    print(f"  {p['topic']}  <- {p['node']}  intra publishes {p['n_ipub']} (with address {p['n_ipub_addr']})  "
          f"subs {len(r['subs'])} = {r['n_shared']} shared + {r['n_own']} ownership -> {r['copies']} copies/publish")
    for s in r['subs']:
        if s is None: print('      (sub not registered?)'); continue
        print(f"      -> {s['node']}  {'shared' if s['take_shared'] else 'OWNERSHIP'} depth {s['depth']}  takes {s['n_take']}"
              f"{'  [NO TAKE EVENTS: take hook not instantiated in this binary]' if s['n_take'] == 0 and p['n_ipub'] > 0 else ''}")
unmatched_subs = [s for k, s in S.items() if not any(m['vpid'] == s['vpid'] and m['sub_id'] == s['sub_id'] for m in M) and sel(s['topic'])]
if unmatched_subs:
    print(f'\nintra-process subscriptions without any matched publisher in their process ({len(unmatched_subs)}; they are fed over DDS or not at all):')
    for s in sorted(unmatched_subs, key=lambda s: (s['vpid'], s['topic'])):
        print(f"  vpid {s['vpid']} {s['topic']}  {s['node']}  {'shared' if s['take_shared'] else 'ownership'} depth {s['depth']}")
no_take = [s for s in S.values() if s['n_take'] == 0 and sel(s['topic']) and any(m['vpid'] == s['vpid'] and m['sub_id'] == s['sub_id'] for m in M)]
print(f'\nmatched intra-process subscriptions with NO fish_rclcpp_intra_take event: {len(no_take)} of '
      f'{sum(1 for s in S.values() if sel(s["topic"]) and any(m["vpid"] == s["vpid"] and m["sub_id"] == s["sub_id"] for m in M))}')
for s in sorted(no_take, key=lambda s: (s['vpid'], s['topic'])):
    print(f"  vpid {s['vpid']} {s['topic']}  {s['node']}  {'shared' if s['take_shared'] else 'ownership'}")
if a.json:
    json.dump(dict(session=a.session, publishers=list(P.values()), subscriptions=list(S.values()), matches=M, per_publisher=rows), open(a.json, 'w'), indent=1, default=str)
    print('wrote', a.json)
